Ускорение: 20×
В 20 раз быстрее
и нулевая фрагментация. Так я решил проблему данных датчиков.
Стратегия 2: статическое распределение для сетевых буферов
Для общения по TCP/IP сетевому стеку требовались буферы. Изначально код распределял их динамически:
// ПЛОХО: Динамическое распределение
typedef struct {
 char *tx_buffer;
 char *rx_buffer;
 // ...
} uart_context_t;

void uart_init(uart_context_t *ctx) {
 ctx->tx_buffer = malloc(1024); // Фрагментация!
 ctx->rx_buffer = malloc(1024);
}

// ХОРОШО: Статическое распределение
typedef struct {
 char tx_buffer[1024];
 char rx_buffer[1024];
 // ...
} uart_context_t;

static uart_context_t g_uart_ctx; // Статическое, без malloc

void uart_init(void) {
 // Буферы уже распределены, ничего делать не нужно
}
Преимущества
:
Нулевая фрагментация
: куча не используется
Нулевой оверхед
: никаких метаданных
Предсказуемость
: всё известно на этапе компиляции
Скорость
: не требуется время на распределение
Минус
: ОЗУ используется, даже если не нужна, но для прошивки это обычно приемлемо.
Стратегия 3: распределение на основе стека
Для временных буферов я использовал стек:
// ПЛОХО: Распределение кучи для временного буфера
void process_data(void) {
 char *temp = malloc(512);
 // ... использование temp
 free(temp);
}

// ХОРОШО: Распределение со стеком
void process_data(void) {
 char temp[512]; // В стеке
 // ... использование temp
 // Освобождение выполняется автоматически, когда функция выполняет возврат
}
Преимущества
:
Наибольшая скорость
: достаточно управлять указателем стека
Отсутствие фрагментации
: стек увеличивается/уменьшается, больше ничего не затрагивая
Автоматическая очистка
: освобождение не требуется
Ограничение
: размер стека ограничен (обычно 4–16 КБ). Не следует распределять в стек большие буферы.
Стратегия 4: области памяти
Можно разбить память на области под различные цели:
// Структура памяти (суммарно 128 КБ)
#define REGION_STATIC_START 0x20000000
#define REGION_STATIC_SIZE (64 * 1024) // 64 КБ под статические данные

#define REGION_POOL_START (REGION_STATIC_START + REGION_STATIC_SIZE)
#define REGION_POOL_SIZE (32 * 1024) // 32 КБ под пулы

#define REGION_STACK_START (REGION_POOL_START + REGION_POOL_SIZE)
#define REGION_STACK_SIZE (16 * 1024) // 16 КБ под стек

#define REGION_DMA_START (REGION_STACK_START + REGION_STACK_SIZE)
#define REGION_DMA_SIZE (16 * 1024) // 16 КБ под буферы DMA

typedef struct {
 uint8_t static_data[REGION_STATIC_SIZE];
 uint8_t pool_memory[REGION_POOL_SIZE];
 uint8_t stack[REGION_STACK_SIZE];
 uint8_t dma_buffers[REGION_DMA_SIZE];
} memory_layout_t;

__attribute__((section(".ram")))
static memory_layout_t g_memory;
Почему это помогает
:
Чёткие границы
: размер каждой области постоянен
Отсутствие помех
: DMA не повреждает стек
Простота отладки
: мы знаем, что каждая область заполнена
Удобство для кэша
: связанные друг с другом данные находятся в одной области
Стратегия 5: Slab‑распределитель
Для объектов одного типа можно использовать slab‑распределитель:
#define MAX_CONNECTIONS 32

typedef struct {
 int socket_fd;
 char rx_buffer[2048];
 char tx_buffer[2048];
 // ... другие поля
} connection_t;

typedef struct {
 connection_t connections[MAX_CONNECTIONS];
 uint32_t free_bitmap; // 1 бит на соединение
} connection_pool_t;

static connection_pool_t g_conn_pool;

connection_t *conn_alloc(void) {
 // Находим первый свободный бит
 int idx = __builtin_ffs(g_conn_pool.free_bitmap) - 1;
 if (idx < 0) {
 return NULL; // Пул исчерпан
 }

 // Отмечаем как используемое
 g_conn_pool.free_bitmap &= ~(1U << idx);

 // Возвращаем соединение
 return &g_conn_pool.connections[idx];
}

void conn_free(connection_t *conn) {
 int idx = conn - g_conn_pool.connections;
 g_conn_pool.free_bitmap |= (1U << idx);
}
Преимущества
:
Распределение за O(1)
: просто находим первый установленный бит
Удобство для кэша
: все соединения непрерывны
Типобезопасность
: распределить можно только connection_t
Низкий оверхед
: по 1 биту на объект
