Пример из реального мира: управление кучей FreeRTOS
В FreeRTOS есть несколько реализаций куч:
heap_1.c: простой Bump Allocator
static uint8_t heap[configTOTAL_HEAP_SIZE];
static size_t next_free_byte = 0;

void *pvPortMalloc(size_t size) {
 void *ptr = NULL;

 if (next_free_byte + size < configTOTAL_HEAP_SIZE) {
 ptr = &heap[next_free_byte];
 next_free_byte += size;
 }

 return ptr;
}

void vPortFree(void *ptr) {
 // No-op: невозможно освободить отдельные блоки
}
Сценарий использования
: системы, которые не могут освобождать память (распределение выполняется только при запуске).
heap_4.c: First‑Fit with Coalescing
typedef struct A_BLOCK_LINK {
 struct A_BLOCK_LINK *pxNextFreeBlock;
 size_t xBlockSize;
} BlockLink_t;

static BlockLink_t xStart;
static BlockLink_t *pxEnd = NULL;

void *pvPortMalloc(size_t xWantedSize) {
 BlockLink_t *pxBlock, *pxPreviousBlock, *pxNewBlockLink;

 // Находим первый достаточно большой блок
 pxPreviousBlock = &xStart;
 pxBlock = xStart.pxNextFreeBlock;

 while ((pxBlock->xBlockSize < xWantedSize) && (pxBlock->pxNextFreeBlock != NULL)) {
 pxPreviousBlock = pxBlock;
 pxBlock = pxBlock->pxNextFreeBlock;
 }

 if (pxBlock != pxEnd) {
 // Разбиваем блок, если он достаточно большой
 // ...
 return (void *)(((uint8_t *)pxPreviousBlock->pxNextFreeBlock) + xHeapStructSize);
 }

 return NULL;
}
Сценарий использования
: распределение общего назначения с допустимой степенью фрагментации.
