}
Сценарий использования
: системы с несколькими областями ОЗУ (внутренняя SRAM + внешняя DRAM).
Соединяем всё вместе: оптимизированная память прошивки
Вот готовая оптимизированная прошивка, объединяющая в себе все описанные выше методики:
// 1. Области памяти
#define STATIC_REGION_SIZE (64 * 1024)
#define POOL_REGION_SIZE (32 * 1024)
#define STACK_REGION_SIZE (16 * 1024)
#define DMA_REGION_SIZE (16 * 1024)

// 2. Пулы фиксированного размера
typedef struct {
 fast_pool_t small_pool; // Блоки по 32 байта
 fast_pool_t medium_pool; // Блоки по 256 байт
 fast_pool_t large_pool; // Блоки по 4096 байт
} pool_manager_t;

static pool_manager_t g_pools;

// 3. Статическое распределение для объектов с долгим сроком жизни
typedef struct {
 char tx_buffer[1024];
 char rx_buffer[1024];
 // ...
} uart_context_t;

static uart_context_t g_uart;

// 4. Slab-распределитель для соединений
typedef struct {
 connection_t connections[MAX_CONNECTIONS];
 uint32_t free_bitmap;
} connection_pool_t;

static connection_pool_t g_conn_pool;

// Инициализация памяти
void memory_init(void) {
 // Инициализация пулов
 pool_init(&g_pools.small_pool, 32, 128);
 pool_init(&g_pools.medium_pool, 256, 32);
 pool_init(&g_pools.large_pool, 4096, 8);

 // Инициализация пула соединений
 g_conn_pool.free_bitmap = 0xFFFFFFFF; // All free

 // Статические объекты уже инициализированы
}

// Функция умного распределения
void *mem_alloc(size_t size) {
 if (size <= 32) {
 return pool_alloc(&g_pools.small_pool);
 } else if (size <= 256) {
 return pool_alloc(&g_pools.medium_pool);
 } else if (size <= 4096) {
 return pool_alloc(&g_pools.large_pool);
 } else {
 return NULL; // Слишком большой
 }
}

void mem_free(void *ptr, size_t size) {
 if (size <= 32) {
 pool_free(&g_pools.small_pool, ptr);
 } else if (size <= 256) {
 pool_free(&g_pools.medium_pool, ptr);
 } else if (size <= 4096) {
 pool_free(&g_pools.large_pool, ptr);
 }
}
